-- -----------------------------------------------------------------------
-- LevelSync: acore_string entries
--   * 100006 - 100008 : auto-sync notifications (LevelSync.cpp),
--                       printf-style format (%%u / %%s).
--   * 100010 - 100090 : command/chat strings (LevelSyncCommands.cpp),
--                       fmt-style format ({} placeholders) consumed by the
--                       templated PSendSysMessage(uint32, Args...) overload.
-- -----------------------------------------------------------------------

DELETE FROM `acore_string` WHERE `entry` BETWEEN 100006 AND 100008;
DELETE FROM `acore_string` WHERE `entry` BETWEEN 100010 AND 100090;

